WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_c_same'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '同地追及', 'kp-trv-c-same', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "同地追及"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "追及距离 = (V快 - V慢) × 追及时间。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "乙先走了一段时间，甲在后面加速追。最终在某处甲追上乙。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "追及问题的本质，是“快的人要把慢的人【提前拉开的距离】给抹平”。所以，所谓的“追及距离”，就是开始追击那一瞬间，两人相隔的距离。"}]}, {"type": "katexBlock", "attrs": {"content": "S_{拉开的差距} = (V_{快} - V_{慢}) \\times T_{追击过程}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[画出追击图] --> B[先算出乙独自提前走了多远 (这就是要追的 S差距)]\nB --> C[提取 V快 和 V慢, 算出速度差 V差 = V快 - V慢]\nC --> D[套用公式: T追击 = S差距 ÷ V差]\nD --> E[注意: 问的是追上时的时刻, 必须加上乙提前走的那个时间段!]"}}]}$$ AS jsonb), NULL, '同地追及的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "同地追及"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_c_same", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
